import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,S as c,T as l,_ as u,b as d,k as f,l as p,n as m,o as h,t as g,v as _}from"./shared-C5BCElVa.js";import{t as v}from"./CodeEditor-BZlrvoTL.js";var y=e();function b({module:e}){return(0,y.jsxs)(a,{children:[(0,y.jsx)(i,{chip:e??`Глава 3 · Блок 10 · HTTP к готовому Planner`,title:`Чтение данных Planner`,intro:`Продолжим работающий FastAPI и подключим к нему тот же Planner, которым пользуется CLI. Сначала разберём путь к данным и получению сервиса, затем вернём список задач и общую статистику.`,variant:`project`}),(0,y.jsxs)(s,{number:`00`,title:`От проверки сервера к чтению Planner`,children:[(0,y.jsx)(o,{children:`В предыдущем шаге мы проверили, что приложение запускается и отвечает на GET /health. Теперь добавим к этому работающему входу чтение задач, которые уже сохраняет Planner.`}),(0,y.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`У нас есть CLI, PlannerService, JsonStorage и приложение FastAPI с проверенным маршрутом health.`},{title:`Новый вопрос`,description:`Как HTTP-обработчик получит настроенный Planner и прочитает то же сохранённое состояние, что видит CLI?`},{title:`Результат`,description:`Мы подключим полный список задач и общую статистику, сохранив одну логику чтения и один источник данных.`}]}),(0,y.jsx)(`p`,{children:`Health подтверждает доступность приложения, но не показывает задачи. В CLI и FastAPI работают разные процессы, и каждый из них создаёт свои объекты Python. Их связывает сохранённый JSON: CLI уже меняет его через PlannerService, а новый API будет читать его через этот же сервис. Поэтому сначала проверим реальный путь файла и состояние CLI, затем подключим GET-маршруты к приложению.`})]}),(0,y.jsxs)(s,{number:`01`,title:`Два процесса обращаются к одному файлу`,children:[(0,y.jsx)(o,{children:`Чтобы API и CLI показывали одни задачи, мы повторно используем готовую конфигурацию проекта, а не передаём объекты между процессами.`}),(0,y.jsx)(`p`,{children:`Когда запускаем CLI, Python создаёт его объекты в памяти этого процесса. Когда отдельно запускаем Uvicorn, у сервера появляется собственная память. Даже если в обоих процессах написать одинаковый код, переменная со списком задач в одном не становится переменной другого. Каждый запускаемый вход строит свой PlannerService, но build_service() по умолчанию передаёт ему JsonStorage с настроенным путём к тому же файлу.`}),(0,y.jsx)(`p`,{children:`У JsonStorage хранится путь, а не постоянная копия списка. При вызове list_tasks() сервис просит хранилище загрузить текущие данные. При успешном изменении add_task() или mark_done() сохраняет новый список. Поэтому после завершённой команды CLI следующий запрос API может прочитать новое состояние без перезапуска Uvicorn.`}),(0,y.jsx)(t,{rows:[[`Память процесса`,`Содержит объекты только запущенного CLI или только приложения Uvicorn.`],[`Настроенный JSON`,`Сохраняет данные между процессами и запусками, потому что оба входа обращаются к одному пути.`]]}),(0,y.jsx)(`p`,{children:`Представим два рабочих кабинета и одну общую бумажную книгу в шкафу. Клиент в первом кабинете записывает изменение в книгу; человек во втором открывает её заново и видит последнюю запись. Кабинеты соответствуют процессам, а книга соответствует JSON-файлу. Это сравнение помогает понять постоянство данных, но не обещает безопасную одновременную запись: в нашей практике мы меняем данные последовательно.`}),(0,y.jsx)(`p`,{children:`Проследим существующую цепочку: CLI использует build_service(), фабрика выбирает настроенный JsonStorage, PlannerService вызывает load() для чтения или save() после успешного изменения. На стороне FastAPI мы повторно вызовем эту фабрику. Путь не будем угадывать по текущей рабочей папке и не создадим демонстрационный JSON рядом с проектом.`}),(0,y.jsx)(`p`,{children:`Чтобы снять baseline, запускаем CLI из корня проекта командой из README. После приглашения «Команда:» вводим list и stats; add добавляет задачу, а exit завершает CLI. Эти слова вводятся внутри CLI, не в PowerShell. Сервис сохраняет задачу в настроенный JSON, поэтому те же list и stats покажут её после нового запуска.`}),(0,y.jsx)(g,{caption:`Путь GET-запроса к сохранённым данным Planner`,orientation:`vertical`,children:(0,y.jsxs)(h,{label:`Последовательность чтения от запроса к JSON`,orientation:`vertical`,children:[(0,y.jsx)(p,{title:`HTTP-клиент`,shape:`terminator`,children:(0,y.jsx)(`p`,{children:`GET /tasks или GET /stats`})}),(0,y.jsx)(m,{label:`отправляет запрос`}),(0,y.jsx)(p,{title:`FastAPI-обработчик`,children:(0,y.jsx)(`p`,{children:`Получает текущий Request`})}),(0,y.jsx)(m,{label:`берёт сервис приложения`}),(0,y.jsx)(p,{title:`app.state.planner`,children:(0,y.jsx)(`p`,{children:`Хранит PlannerService`})}),(0,y.jsx)(m,{label:`вызывает чтение`}),(0,y.jsx)(p,{title:`PlannerService`,children:(0,y.jsx)(`p`,{children:`list_tasks() или get_statistics()`})}),(0,y.jsx)(m,{label:`запрашивает свежие данные`}),(0,y.jsx)(p,{title:`JsonStorage`,shape:`database`,children:(0,y.jsx)(`p`,{children:`Читает настроенный JSON-файл`})})]})}),(0,y.jsx)(`p`,{children:`Стрелки показывают путь выполнения вызовов от запроса к файлу. Содержимое проходит обратно: хранилище возвращает Task сервису, сервис возвращает результат обработчику, а FastAPI превращает Python-список или словарь в JSON ответа. CLI идёт к тому же хранилищу через собственный сервис в отдельном процессе.`})]}),(0,y.jsxs)(s,{number:`02`,title:`Request даёт доступ к сервису текущего приложения`,children:[(0,y.jsx)(o,{children:`FastAPI передаёт объект Request обработчику. Через него мы найдём сервис, сохранённый в app.state, и вызовем его внутри запроса.`}),(0,y.jsx)(`p`,{children:`Request описывает принятое HTTP-обращение и содержит ссылку на приложение, которое его обрабатывает. Мы указываем Request параметром функции с типом из fastapi. FastAPI распознаёт этот параметр и передаёт объект сам, так же как связывает path-параметры с аргументами обработчика. Для этого шага достаточно двух частей: request.app указывает на приложение, а request.app.state хранит значения, связанные с ним.`}),(0,y.jsx)(`p`,{children:`При запуске создаём FastAPI-приложение и один раз помещаем в его state результат build_service(). Там лежит PlannerService, а не загруженный список задач. Это важно: сервис умеет обращаться к настроенному хранилищу, а новый список он получает только при вызове операции. Так обработчик не добавляет собственные правила чтения и не заводит второй источник данных.`}),(0,y.jsx)(`p`,{children:`На независимом примере запомним название страницы приложения и вернём его через маршрут. В функции не ищем глобальный объект приложения: FastAPI даёт нам Request именно того приложения, которое приняло обращение.`}),(0,y.jsx)(v,{caption:`Независимый пример: значение приложения через Request`,code:`from fastapi import FastAPI, Request

app = FastAPI()
app.state.banner = 'План работает'

@app.get('/about')
def about(request: Request):
    return {'banner': request.app.state.banner}`}),(0,y.jsx)(`p`,{children:`Здесь banner хранится в приложении и доступен обработчику. В Planner на этом же месте находится сервис: request.app.state.planner. Вызов этого свойства сам не читает JSON; он только возвращает выбранный PlannerService. Затем мы внутри обработчика вызываем нужный метод сервиса.`}),(0,y.jsx)(d,{question:`Что находится в request.app.state.planner после настройки приложения?`,options:[`Список задач, загруженный один раз при импорте`,`Выбранный PlannerService, который умеет читать настроенное хранилище`,`Путь HTTP-маршрута /tasks`],correctIndex:1,explanation:`State хранит сервис приложения. Список задач сервис запрашивает у JsonStorage при вызове операции, поэтому изменение файла через CLI не требует пересоздавать список.`}),(0,y.jsx)(`p`,{children:`Мы передаём Request всем обработчикам, которым нужен Planner. Такой доступ связан с текущим приложением и сохраняет один понятный путь при дальнейшем переносе маршрутов в APIRouter. Пока маршруты остаются в app/api.py; отдельный роутер и тестовые подмены ещё не добавляем.`})]}),(0,y.jsxs)(s,{number:`03`,title:`Публичный ответ выбирает нужные поля`,children:[(0,y.jsx)(o,{children:`Доменная Task и HTTP-ответ решают разные задачи. Мы вернём из API только поля публичного договора, оставив полную запись без изменений.`}),(0,y.jsx)(`p`,{children:`У Task есть id, title, priority, is_done и tags. Эти значения нужны самому Planner, но текущий ответ API содержит ровно id, title, priority и is_done. Поле tags остаётся в объекте и в JSON-файле, хотя клиенту этого маршрута оно не выдаётся. Пропуск поля в ответе не удаляет его из задачи и не меняет сохранённые данные.`}),(0,y.jsx)(`p`,{children:`Для такой выборки используют явную проекцию: из более полной записи собирают меньший объект ответа. Сначала разберём её на другом примере, не связанном с задачами Planner. В карточке книги оставим название и автора, а внутреннюю заметку не будем передавать читателю.`}),(0,y.jsx)(v,{caption:`Пример выборки полей для отдельной карточки`,code:`edition = {'title': 'Лесной маршрут', 'author': 'М. Лебедев', 'internal_note': 'проверить макет'}
card = {'title': edition['title'], 'author': edition['author']}
print(card)`}),(0,y.jsx)(`p`,{children:`Мы явно перечислили поля новой карточки. Словарь card не является полной записью edition, а выборка значений не меняет исходный словарь. В обработчике Planner применим ту же идею к объекту Task: одна небольшая функция _task_read_data(task) собирает четыре публичных значения. Отдельный helper пригодится обоим маршрутам и следующему item-запросу.`}),(0,y.jsx)(`p`,{children:`Вторая аналогия: полная запись похожа на архивную папку, а проекция на окно выдачи, через которое видна только нужная карточка. Мы меняем вид ответа, но не содержимое папки. Граница сравнения проста: в проекте проекция создаётся обычным Python-словарём из атрибутов Task, не отдельным хранилищем и не копией доменной модели.`}),(0,y.jsx)(_,{code:`edition = {'title': 'Лесной маршрут', 'author': 'М. Лебедев', 'internal_note': 'черновик'}
card = {'title': edition['title'], 'author': edition['author']}
print(card)`,steps:[{line:1,note:`В card начинаем собирать отдельный словарь. edition остаётся полной исходной записью.`,vars:{edition:`{title, author, internal_note}`}},{line:1,note:`Берём значение title из edition и связываем его с ключом title новой карточки.`,vars:{"edition['title']":`'Лесной маршрут'`}},{line:1,note:`Точно так же добавляем автора. Ключ internal_note в card не появляется.`,vars:{card:`{'title': 'Лесной маршрут', 'author': 'М. Лебедев'}`}},{line:2,note:`print показывает выбранные поля. Исходный edition по-прежнему содержит внутреннюю заметку.`,vars:{result:`{'title': 'Лесной маршрут', 'author': 'М. Лебедев'}`}}]}),(0,y.jsx)(`p`,{children:`В нашем API helper будет работать с объектом Task, а не со словарём из примера. Поэтому обращение к полям будет через task.id и task.title. В списке мы применим функцию к каждой задаче и получим список словарей одинаковой формы. Теперь проверим, что увидит клиент, если обработчик вернёт доменный объект целиком.`}),(0,y.jsx)(n,{code:`@app.get('/tasks')
def read_tasks(request: Request):
    tasks = request.app.state.planner.list_tasks()
    return [task.to_dict() for task in tasks]`,question:`Какое нарушение публичного договора может появиться в этом ответе?`,options:[`GET обязательно превращается в запись в JSON-файл`,`Полный to_dict может включить внутреннее поле tags`,`Пустая коллекция обязательно становится ответом 404`],correctIndex:1,explanation:`Доменное представление содержит больше полей, чем договор ответа. Для маршрута нужна явная проекция из четырёх значений, а исходная Task должна остаться полной.`})]}),(0,y.jsxs)(s,{number:`04`,title:`GET /tasks возвращает актуальную коллекцию`,children:[(0,y.jsx)(o,{children:`Теперь соединим знакомый list_tasks() с публичной проекцией. Каждый вызов маршрута получает полный список из текущего состояния Planner.`}),(0,y.jsx)(`p`,{children:`Collection означает весь набор задач, а не одну выбранную запись. Обработчик GET /tasks получает Planner через Request, вызывает list_tasks() и применяет _task_read_data к каждому элементу. Никаких фильтров, сортировки или ограничения размера здесь пока нет. Эти операции изменили бы смысл полного list_tasks и относятся к следующему этапу работы с выборкой.`}),(0,y.jsx)(`p`,{children:`FastAPI принимает возвращённый обработчиком Python-список словарей и сам формирует JSON-ответ. Мы возвращаем структуру данных, а не печатаем её через print и не собираем JSON вручную строкой. Если хранилище пустое, метод вернёт пустой список, а маршрут ответит JSON-массивом []. Это успешное чтение пустой коллекции; 404 относится к запросу одной задачи, которой нет.`}),(0,y.jsx)(`p`,{children:`Следующий пример сравнивает два места чтения. В первом список запрашивается при каждом обращении. Во втором он загружен при импорте модуля и остаётся старым после изменения через CLI. Нам нужна первая последовательность.`}),(0,y.jsx)(l,{question:`Какой вариант покажет изменения JSON после завершённой команды CLI, пока Uvicorn остаётся запущенным?`,left:{title:`Читаем внутри запроса`,code:`def titles(request: Request):
    planner = request.app.state.planner
    return [task.title for task in planner.list_tasks()]`,note:`Сервис запрашивает текущее состояние в момент вызова маршрута.`},right:{title:`Сохраняем список при импорте`,code:`tasks = build_service().list_tasks()

def titles(request: Request):
    return [task.title for task in tasks]`,note:`Переменная tasks хранит снимок, созданный до следующего изменения файла.`},preferred:`left`,explanation:`Список должен загружаться через сервис внутри каждого обработчика. При первом варианте следующий GET увидит сохранённое CLI изменение, при втором ответ останется привязан к прежнему списку.`}),(0,y.jsx)(`p`,{children:`Слово «актуальный» здесь имеет точный смысл: новый вызов list_tasks() читает файл, настроенный в уже собранном JsonStorage. Мы не обещаем, что два параллельных изменения безопасно объединятся; сначала завершаем CLI-команду, затем отправляем GET и сравниваем состояние.`})]}),(0,y.jsxs)(s,{number:`05`,title:`GET /stats использует готовый подсчёт`,children:[(0,y.jsx)(o,{children:`Общую статистику уже считает PlannerService. В API мы переименуем один ключ ответа и сохраним все значения сервиса.`}),(0,y.jsx)(`p`,{children:`get_statistics() возвращает словарь с ключами all, open и done. В публичной форме общий ключ называется total, а open и done сохраняют прежние имена. Мы не считаем задачи новым циклом в обработчике и не выводим total из HTTP-списка. Сервис загружает полный источник данных и остаётся единственным местом предметного подсчёта.`}),(0,y.jsx)(`p`,{children:`Это различие важно, потому что список и статистика отвечают на разные вопросы. GET /tasks показывает сами записи; GET /stats даёт общий итог по Planner. Сейчас список полный, но в следующем занятии он будет расширен выборкой. Статистика всё равно должна относиться ко всему хранилищу, а не только к видимой части ответа.`}),(0,y.jsx)(`p`,{children:`На независимом примере переименуем ключи готового отчёта. Числа останутся прежними, даже если названия в ответе поменялись.`}),(0,y.jsx)(u,{code:`service_counts = {'all': 5, 'current': 3, 'closed': 2}
report = {'total': service_counts['all'], 'active': service_counts['current'], 'archived': service_counts['closed']}
print(report)`,output:`{'total': 5, 'active': 3, 'archived': 2}`,hint:`Мы не пересчитываем исходные значения, только читаем их и записываем под другими ключами.`}),(0,y.jsx)(`p`,{children:`В результате total равен прежнему all. Аналогично маршрут Planner переносит значение all в total, а open и done берёт напрямую. Если задач нет, правильная статистика имеет нули во всех трёх полях; отсутствие элементов не превращает общий маршрут статистики в 404.`}),(0,y.jsx)(c,{statement:`GET /stats должен считать только те задачи, которые уже вернул GET /tasks.`,isTrue:!1,explanation:`Статистика вызывает get_statistics() и охватывает весь источник. Она не зависит от списка ответа или его будущего ограничения.`}),(0,y.jsx)(c,{statement:`Если JsonStorage пуст, GET /tasks возвращает пустой список, а GET /stats возвращает нулевые значения.`,isTrue:!0,explanation:`Пустая коллекция является допустимым состоянием Planner. Отсутствующий отдельный id и пустой список имеют разный смысл.`})]}),(0,y.jsxs)(s,{number:`06`,title:`Чтение свежих данных не изменяет Planner`,children:[(0,y.jsx)(o,{children:`Последняя проверка связывает оба входа. Мы изменяем сохранённое состояние через CLI, затем читаем его через работающий API и после нового запуска.`}),(0,y.jsx)(`p`,{children:`GET-маршруты вызывают только операции чтения. list_tasks() и get_statistics() загружают данные, но не вызывают save(), поэтому сами запросы не меняют файл. CLI-команда add создаёт открытую задачу с новым id. После неё total и open увеличатся на один, а done останется прежним. После перезапуска Uvicorn новый сервис прочитает тот же настроенный JSON.`}),(0,y.jsx)(`p`,{children:`Пустое хранилище и ошибка чтения файла не равны. В принятом договоре отсутствие задач даёт пустой список и нулевые счётчики. Повреждённый JSON или ошибка доступа остаётся StorageError из готового слоя. Мы не ловим её как будто данных нет, не возвращаем 404 и не создаём отдельную ветку обработки в каждом маршруте.`}),(0,y.jsx)(`p`,{children:`Проверяем шаги по очереди: завершаем и закрываем CLI, затем фиксируем текущее содержимое JSON, после чего отправляем GET и сравниваем файл ещё раз. Так мы отделяем запись CLI от чтения API. Если сравнить файл до add с файлом после запросов, изменение CLI можно ошибочно принять за побочный эффект GET. Параллельную запись этот порядок не защищает.`}),(0,y.jsx)(r,{tone:`info`,children:`Здесь мы не добавляем кэш задач, второй список в app.state или собственную работу с путём файла. В state лежит сервис; актуальные Task каждый раз запрашиваются через его существующий метод.`}),(0,y.jsx)(`p`,{children:`Проверим ещё одно свойство чтения: GET после завершённой команды CLI должен увидеть сохранённое изменение. Посмотрим, что произойдёт, если список загрузили до запроса и повторно используют в обработчике.`}),(0,y.jsx)(n,{code:`tasks = build_service().list_tasks()

@app.get('/tasks')
def read_tasks(request: Request):
    return [_task_read_data(task) for task in tasks]`,question:`Почему следующий GET /tasks может не показать задачу, которую CLI уже сохранил?`,options:[`Список tasks загружен до запроса и повторно используется каждым вызовом`,`GET-обработчик не может вызывать методы PlannerService`,`Чтение через JsonStorage автоматически перезапускает Uvicorn`],correctIndex:0,explanation:`build_service().list_tasks() выполняется при импорте модуля, поэтому tasks остаётся старым снимком. Обработчик должен получить Planner через Request и вызвать list_tasks() внутри запроса; затем _task_read_data задаёт публичную форму.`})]}),(0,y.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(o,{children:`Пройдём путь от уже работающего health до двух проверенных ответов, сверяя каждую часть с реальным Planner.`}),(0,y.jsx)(f,{variant:`connected`,items:[{title:`Проверим точку входа и данные`,description:`Мы подтвердим состояние app/api.py, путь build_service() и фактический список CLI, затем сохраним baseline.`},{title:`Подключим список`,description:`Мы получим Planner через Request и app.state, применим общую проекцию, а GET /tasks сравним с полным CLI-list.`},{title:`Добавим статистику`,description:`Мы вызовем готовый get_statistics(), перенесём all в total и сверим все значения с CLI.`},{title:`Проверим свежесть`,description:`Мы изменим данные через CLI, повторим GET без перезапуска Uvicorn и подтвердим, что JSON не изменился от чтения.`}]}),(0,y.jsx)(`p`,{children:`Результат практики нужен следующему занятию: из работающего списка мы возьмём реальный положительный id, а helper публичной проекции и способ получить Planner останутся общими. В 48.1 этот id станет входом маршрута одной задачи; там появятся Path, граница положительного числа и различие 422/404.`}),(0,y.jsx)(`p`,{children:`Сначала мы подтверждаем готовый результат 47.1: /health отвечает, Swagger или сохранённый Local-запрос обращается к этому приложению, а прежний CLI работает отдельно. Если эта входная опора не готова, мы отмечаем конкретный сбой и не выдаём планируемые маршруты за существующие. В текущем занятии не добавляем query-фильтры, sort/limit, item-route, Pydantic-схемы или новые правила хранения. Практика завершается только после сравнения полного списка и статистики с CLI до и после изменения данных.`})]})]})}export{b as Lesson48};